package android.webkit;import java.util.*;public class WebView extends android.view.View{public static ArrayList<WebView> created=new ArrayList<>();public WebSettings settings=new WebSettings();public WebViewClient client;public ArrayList<String> history=new ArrayList<>();public int index=-1,reloads,stops;public boolean paused,destroyed;public WebView(android.content.Context c){super(c);created.add(this);}public WebSettings getSettings(){return settings;}public void setWebViewClient(WebViewClient c){client=c;}public String url(){return index<0?null:history.get(index);}public void loadUrl(String url){while(history.size()>index+1)history.remove(history.size()-1);history.add(url);index++;if(client!=null)client.onPageFinished(this,url);}public boolean canGoBack(){return index>0;}public boolean canGoForward(){return index+1<history.size();}public void goBack(){if(canGoBack())index--;}public void goForward(){if(canGoForward())index++;}public void reload(){reloads++;}public void onPause(){paused=true;}public void onResume(){paused=false;}public void stopLoading(){stops++;}public void destroy(){destroyed=true;}}